#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ActionConfig {
    pub max_charge_ms: u32,
    pub swing_ms: u32,
    pub recovery_ms: u32,
    pub energy_per_ms: u32,
    pub base_damage: u32,
    pub bonus_damage: u32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConfigError { ZeroMaxCharge }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Phase { Charging, Swing, Recovery, Finished }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Strike {
    pub charge_ms: u32,
    pub damage: u32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Advance {
    None,
    Struck(Strike),
    PhaseChanged(Phase),
    Finished,
}

#[derive(Debug, Clone)]
pub struct ChargedAction {
    config: ActionConfig,
    phase: Phase,
    elapsed: u32,
}

impl ChargedAction {
    pub fn new(config: ActionConfig) -> Result<ChargedAction, ConfigError> {
        if config.max_charge_ms == 0 {
            return Err(ConfigError::ZeroMaxCharge);
        }
        Ok(ChargedAction {
            config,
            phase: Phase::Charging,
            elapsed: 0,
        })
    }

    pub fn phase(&self) -> Phase {
        self.phase
    }

    pub fn advance(&mut self, delta_ms: u32, held: bool, energy: &mut u32) -> Advance {
        match self.phase {
            Phase::Charging => {
                if !held {
                    return self.strike();
                }

                let capacity = self.config.max_charge_ms - self.elapsed;
                let requested = delta_ms.min(capacity);
                let charged_ms = if self.config.energy_per_ms == 0 {
                    requested
                } else {
                    requested.min(*energy / self.config.energy_per_ms)
                };
                let cost = charged_ms * self.config.energy_per_ms;
                *energy -= cost;
                self.elapsed += charged_ms;

                if self.elapsed == self.config.max_charge_ms || charged_ms < requested {
                    self.strike()
                } else {
                    Advance::None
                }
            }
            Phase::Swing => {
                self.elapsed = self.elapsed.saturating_add(delta_ms);
                if self.elapsed >= self.config.swing_ms {
                    self.phase = Phase::Recovery;
                    self.elapsed = 0;
                    Advance::PhaseChanged(Phase::Recovery)
                } else {
                    Advance::None
                }
            }
            Phase::Recovery => {
                self.elapsed = self.elapsed.saturating_add(delta_ms);
                if self.elapsed >= self.config.recovery_ms {
                    self.phase = Phase::Finished;
                    self.elapsed = 0;
                    Advance::Finished
                } else {
                    Advance::None
                }
            }
            Phase::Finished => Advance::Finished,
        }
    }

    pub fn interrupt(&mut self) {
        self.phase = Phase::Finished;
        self.elapsed = 0;
    }

    fn strike(&mut self) -> Advance {
        let bonus = self
            .config
            .bonus_damage
            .saturating_mul(self.elapsed)
            / self.config.max_charge_ms;
        let strike = Strike {
            charge_ms: self.elapsed,
            damage: self.config.base_damage.saturating_add(bonus),
        };
        self.phase = Phase::Swing;
        self.elapsed = 0;
        Advance::Struck(strike)
    }
}
